// 不建第二事务或动作钟；本人命令和NPC候选均借同一实际权源与任务入口。
#include "diplomacy_integration.hpp"
namespace hanmo::resident {
namespace {
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
DiplomaticPresentRead present_read(const DiplomacyReadContext& c){return {c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,c.interaction,c.interaction_catalog,c.interaction_access};}
template<class T>Status status(const Outcome<T>& out){return out.ok?common_success():Status{false,{},out.error};}
EnvoyContactAuthorization contact_service(const DiplomacyReadContext& c){return [&c](const EnvoyTaskAcceptance& accepted,const FaceToFaceContactProof& proof){return preview_diplomatic_mission_contact(present_read(c),accepted.mission_authority_fact_id,accepted.envoy_actor_id,proof);};}
EnvoyReportAuthorization report_service(const DiplomacyReadContext& c){return [&c](const EnvoyTaskAcceptance& a,const EnvoyTaskDelivery& delivery,const FaceToFaceContactProof& proof){return preview_diplomatic_report_contact(present_read(c),a.mission_authority_fact_id,a.envoy_actor_id,delivery.diplomatic_presentation_fact_id,proof);};}
bool reports_enabled(const DiplomacyReadContext& c){return c.diplomacy.version==2&&c.diplomacy_catalog.version==2&&c.envoy_tasks.version==2&&c.diplomacy.v2&&c.diplomacy_catalog.v2;}
}
DiplomacyReadContext DiplomacyWriteContext::read()const{return {common,common_catalog,organization,organization_catalog,diplomacy,diplomacy_catalog,interaction,interaction_catalog,interaction_access,tasks,envoy_tasks,activity,view_index,navigation};}
bool diplomacy_command_kind(const StableId& kind){return kind=="diplomatic_propose_passage"||kind=="diplomatic_commission_envoy"||kind=="diplomatic_present_passage"||kind=="diplomatic_reply_passage"||kind=="envoy_accept"||kind=="envoy_deliver"||kind=="envoy_cancel"||kind=="envoy_report"||kind=="diplomatic_delegate_envoy";}
StableId diplomacy_command_kind(const DiplomacyCommand& command){return std::visit([](const auto& c)->StableId{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,DiplomaticProposeCommand>)return "diplomatic_propose_passage";else if constexpr(std::is_same_v<T,DiplomaticMissionCommand>)return "diplomatic_commission_envoy";else if constexpr(std::is_same_v<T,DiplomaticPresentCommand>)return "diplomatic_present_passage";else if constexpr(std::is_same_v<T,DiplomaticReplyCommand>)return "diplomatic_reply_passage";else if constexpr(std::is_same_v<T,DiplomaticEnvoyAcceptCommand>)return "envoy_accept";else if constexpr(std::is_same_v<T,DiplomaticEnvoyDeliverCommand>)return "envoy_deliver";else if constexpr(std::is_same_v<T,DiplomaticEnvoyReportCommand>)return "envoy_report";else if constexpr(std::is_same_v<T,DiplomaticDelegateCommand>)return "diplomatic_delegate_envoy";else return "envoy_cancel";},command);}
Outcome<DiplomacyQuote> preview_diplomacy_business(const DiplomacyReadContext& c,const StableId& actor,const DiplomacyCommand& command){
    if(!c.diplomacy_catalog.enabled)return {false,{},common_failure("DiplomacyUnavailable").error};DiplomacyQuote quote{c.common.state().identity,actor,command,0};DiplomaticMissionAccess missions(c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy);
    auto checked=std::visit([&](const auto& cmd)->Status{using T=std::decay_t<decltype(cmd)>;
        if constexpr(std::is_same_v<T,DiplomaticProposeCommand>)return status(preview_diplomatic_proposal(c.common,c.common_catalog,c.organization,c.organization_catalog,c.diplomacy_catalog,c.activity,actor,cmd));
        else if constexpr(std::is_same_v<T,DiplomaticMissionCommand>)return status(preview_diplomatic_mission(c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,actor,cmd));
        else if constexpr(std::is_same_v<T,DiplomaticPresentCommand>)return status(preview_diplomatic_presentation(present_read(c),actor,cmd));
        else if constexpr(std::is_same_v<T,DiplomaticReplyCommand>)return status(preview_diplomatic_reply(present_read(c),actor,cmd));
        else if constexpr(std::is_same_v<T,DiplomaticDelegateCommand>){if(!reports_enabled(c))return common_failure("DiplomaticReportVersionRequired");return status(preview_diplomatic_delegation(present_read(c),c.common_catalog,c.activity,*c.diplomacy_catalog.v2,*c.diplomacy.v2,actor,cmd));}
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyReportCommand>){if(!reports_enabled(c))return common_failure("DiplomaticReportVersionRequired");const auto* owned=c.envoy_tasks.envoy_contracts.find(cmd.task_id);if(!owned||owned->acceptance.envoy_actor_id!=actor)return common_failure("TaskNotKnown");auto report=preview_envoy_report(c.common,c.tasks,c.envoy_tasks,c.interaction,c.interaction_catalog,c.interaction_access,missions,missions,actor,cmd.task_id,cmd.provider_actor_id,cmd.expected_world_revision,report_service(c));if(report.ok)quote.duration=report.value.duration_ticks;return status(report);}
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyAcceptCommand>)return status(preview_envoy_task_acceptance(c.common,c.envoy_tasks,missions,actor,cmd.authority_fact_id,cmd.expected_world_revision));
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyDeliverCommand>){auto delivery=preview_envoy_delivery(c.common,c.tasks,c.envoy_tasks,c.interaction,c.interaction_catalog,c.interaction_access,missions,missions,actor,cmd.task_id,cmd.provider_actor_id,cmd.expected_world_revision,contact_service(c));if(delivery.ok)quote.duration=delivery.value.duration_ticks;return status(delivery);}
        else return status(preview_envoy_cancellation(c.common,c.tasks,c.envoy_tasks,missions,missions,actor,cmd.task_id,cmd.expected_world_revision));
    },command);if(!checked.ok)return {false,{},checked.error};return {true,std::move(quote),{}};
}
// 报价冻结具体选择；执行必须当前同identity、同命令，并重新读取本次会面和权责。
Outcome<DiplomacyEffects> apply_diplomacy_business(DiplomacyWriteContext& c,const StableId& actor,const DiplomacyCommand& command,const DiplomacyQuote& quote){
    if(!same_identity(c.common.state().identity,quote.identity)||actor!=quote.actor_id||diplomacy_command_kind(command)!=diplomacy_command_kind(quote.command)||!compare_boundary(encode_diplomacy_command(command),encode_diplomacy_command(quote.command)).exact())return {false,{},common_failure("StaleDiplomacyQuote").error};const auto read=c.read();auto fresh=preview_diplomacy_business(read,actor,command);if(!fresh.ok)return {false,{},fresh.error};if(fresh.value.duration!=quote.duration)return {false,{},common_failure("StaleDiplomacyQuote").error};DiplomaticMissionAccess missions(c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy);
    return std::visit([&](const auto& cmd)->Outcome<DiplomacyEffects>{using T=std::decay_t<decltype(cmd)>;
        if constexpr(std::is_same_v<T,DiplomaticProposeCommand>){auto id=propose_diplomatic_offer_in_transaction(c.common,c.common_catalog,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,c.activity,actor,cmd);if(!id.ok)return {false,{},id.error};return {true,{id.value,{},{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticMissionCommand>){auto id=authorize_diplomatic_mission_in_transaction(c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,actor,cmd);if(!id.ok)return {false,{},id.error};return {true,{id.value,{},{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticPresentCommand>){auto proof=preview_diplomatic_presentation(present_read(read),actor,cmd);if(!proof.ok)return {false,{},proof.error};auto id=present_diplomatic_offer_in_transaction(c.common,c.diplomacy,present_read(read),actor,cmd,proof.value);if(!id.ok)return {false,{},id.error};return {true,{id.value,{},{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticReplyCommand>){auto proof=preview_diplomatic_reply(present_read(read),actor,cmd);if(!proof.ok)return {false,{},proof.error};auto id=reply_diplomatic_offer_in_transaction(c.common,c.diplomacy,present_read(read),actor,cmd,proof.value);if(!id.ok)return {false,{},id.error};return {true,{id.value,{},{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticDelegateCommand>){auto id=delegate_diplomatic_mission_in_transaction(c.common,c.diplomacy,*c.diplomacy.v2,present_read(read),c.common_catalog,c.activity,*c.diplomacy_catalog.v2,actor,cmd);if(!id.ok)return {false,{},id.error};return {true,{id.value,{},{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyReportCommand>){auto action=begin_envoy_report_in_candidate(c.common,c.tasks,c.envoy_tasks,c.interaction,c.interaction_catalog,c.interaction_access,missions,missions,actor,cmd.task_id,cmd.provider_actor_id,cmd.expected_world_revision,report_service(read));if(!action.ok)return {false,{},action.error};return {true,{{},cmd.task_id,action.value},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyAcceptCommand>){auto accepted=accept_envoy_task_in_candidate(c.common,c.tasks,c.envoy_tasks,c.common_catalog,missions,actor,cmd.authority_fact_id,cmd.expected_world_revision);if(!accepted.ok)return {false,{},accepted.error};return {true,{accepted.value.fact_id,accepted.value.task_id,{}},{}};}
        else if constexpr(std::is_same_v<T,DiplomaticEnvoyDeliverCommand>){auto action=begin_envoy_delivery_in_candidate(c.common,c.tasks,c.envoy_tasks,c.interaction,c.interaction_catalog,c.interaction_access,missions,missions,actor,cmd.task_id,cmd.provider_actor_id,cmd.expected_world_revision,contact_service(read));if(!action.ok)return {false,{},action.error};return {true,{{},cmd.task_id,action.value},{}};}
        else {auto cancelled=cancel_envoy_task_in_candidate(c.common,c.tasks,c.envoy_tasks,missions,missions,actor,cmd.task_id,cmd.expected_world_revision,c.release_action);if(!cancelled.ok)return {false,{},cancelled.error};return {true,{cancelled.value.fact_id,cmd.task_id,{}},{}};}
    },command);
}
}
